package android.os;import java.util.*;public class Bundle extends HashMap<String,Object>{public Bundle(){}public Bundle(Bundle b){putAll(b);}public String getString(String k){return (String)get(k);}public String getString(String k,String d){return (String)getOrDefault(k,d);}public void putString(String k,String v){put(k,v);}public void putBoolean(String k,boolean v){put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(get(k));}public CharSequence getCharSequence(String k){return (CharSequence)get(k);}public CharSequence getCharSequence(String k,CharSequence d){return (CharSequence)getOrDefault(k,d);}public void putCharSequence(String k,CharSequence v){put(k,v);}public CharSequence[] getCharSequenceArray(String k){return (CharSequence[])get(k);}}